/* VGA-build variant of sota_wad.S: bakes sota_pico.wad (which has audio
 * transcoded to mono QOA at 11 kHz) instead of sota.wad. Generated by
 * `python3 build_demo.py --audio-format=qoa --output=sota_pico.wad`. */

    .section .rodata.sota_wad, "a"
    .balign 4

    .global _sota_wad_start
_sota_wad_start:
    .incbin "sota_pico.wad"
    .global _sota_wad_end
_sota_wad_end:

    .global _sota_wad_size
    .balign 4
_sota_wad_size:
    .word _sota_wad_end - _sota_wad_start
